<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
const props=defineProps<{courseId:string}>(),emit=defineEmits<{close:[];updated:[]}>()
type Remote={id:string;name:string;revision:number;legacy:boolean}
const dialog=ref<HTMLDialogElement|null>(null),busy=ref(false),error=ref(''),notice=ref(''),configured=ref(false),connected=ref(false),localCount=ref(0),syncedCount=ref(0),documents=ref<Remote[]>([])
const controller=new AbortController()
const explanations:Record<string,string>={sync_not_configured:'尚未配置云同步服务，请先完成本机后台的同步连接配置。',sync_invalid_server:'同步服务地址不正确，请检查后台配置。',sync_unauthorized:'同步凭证无效，请检查本机与云端的配置。',sync_conflict:'云端已有不同版本，已停止上传，保留两边的数据。',local_changes:'本机有尚未上传的改动，已停止下载，避免覆盖。',course_busy:'这节课仍有任务正在处理，请完成后再同步。',sync_unavailable:'暂时连不上云端，本机课程仍可正常使用。',sync_server_error:'云端暂时无法完成同步，请稍后再试。',course_not_found:'找不到这节课的记录。',sync_invalid_reply:'云端返回的数据未通过校验，未覆盖本机记录。'}
async function call(path:string,method='GET'){const response=await fetch('http://127.0.0.1:18080/api/sync'+path,{method,signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(explanations[data.error]||'同步未完成，本机数据已保留。');return data}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action()}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'同步未完成。'}finally{busy.value=false}}
async function status(){const data=await call('/status');configured.value=data.configured;localCount.value=data.localCourses;syncedCount.value=data.syncedCourses}
async function connect(){await run(async()=>{const data=await call('/connection','POST');connected.value=data.connected;documents.value=data.documents;notice.value='云端连接正常。'})}
async function push(){if(!props.courseId)return;await run(async()=>{await call('/courses/'+encodeURIComponent(props.courseId)+'/push','POST');await status();notice.value='当前课程已上传到云端。';connected.value=false;documents.value=[]})}
async function pull(id:string){await run(async()=>{await call('/courses/'+encodeURIComponent(id)+'/pull','POST');await status();notice.value='课程已保存到本机，可从历史记录打开。';emit('updated')})}
onMounted(()=>{dialog.value?.showModal();void run(status)})
onBeforeUnmount(()=>controller.abort())
</script>
<template><dialog ref="dialog" class="sync-dialog" aria-label="云同步" @cancel.prevent="!busy&&emit('close')"><header><div><h2>云同步</h2><p>课程先保存在本机，需要时再连接云端。</p></div><button type="button" class="secondary" :disabled="busy" @click="emit('close')">关闭</button></header><div class="sync-summary"><span>本机 {{ localCount }} 节课程</span><span>已同步 {{ syncedCount }} 节</span></div><p class="sync-scope">同步字幕、导图、AI 解读、练习和课程对话。原视频、图片及随手笔记暂保存在本机。</p><p v-if="!configured&&!busy" class="sync-note">尚未配置云同步服务，本地使用不受影响。</p><div class="sync-actions"><button type="button" class="secondary" :disabled="busy||!configured" @click="connect">{{ busy?'正在处理…':'连接云端并查看课程' }}</button><button type="button" class="run" :disabled="busy||!configured||!courseId" @click="push">上传当前课程</button></div><p v-if="!courseId" class="sync-note">先从历史记录打开一节课程，即可上传。</p><p v-if="error" role="alert" class="sync-error">{{ error }}</p><p v-if="notice" role="status" class="sync-notice">{{ notice }}</p><section v-if="connected" class="remote-courses"><h3>云端课程</h3><p v-if="!documents.length">云端还没有课程。</p><article v-for="item in documents" :key="item.id"><div><strong>{{ item.name||'课程记录' }}</strong><small>{{ item.legacy?'原 MySQL 历史记录':'版本 '+item.revision }}</small></div><button type="button" class="secondary" :disabled="busy" @click="pull(item.id)">下载到本机</button></article></section></dialog></template>
<style scoped>
.sync-dialog{width:min(640px,94vw);max-height:85vh;box-sizing:border-box;padding:26px;border:1px solid #d9e3fa;border-radius:20px;background:#f9fbff;color:#233758;box-shadow:0 24px 80px #13275238}.sync-dialog::backdrop{background:#101d3c88}.sync-dialog header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.sync-dialog h2{margin:0;font-size:22px}.sync-dialog header p,.sync-scope,.sync-note{font-size:13px;line-height:1.8;color:#6b7e9e}.sync-summary{display:flex;gap:22px;padding:18px;background:#edf3ff;border-radius:12px;margin:20px 0}.sync-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.sync-error{color:#a34646;font-size:13px;line-height:1.8}.sync-notice{color:#277758;font-size:13px}.remote-courses h3{font-size:16px}.remote-courses article{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid #e1e8f7;padding:14px 0}.remote-courses article div{display:grid;gap:7px;min-width:0}.remote-courses strong{overflow-wrap:anywhere;font-size:14px}.remote-courses small{color:#7a8ba5;font-size:12px}button:disabled{opacity:.5}@media(max-width:600px){.sync-dialog{padding:18px}.sync-summary{flex-wrap:wrap;gap:10px}.remote-courses article{flex-wrap:wrap}}
</style>
